    # Follows a naive nearest-in-id heuristic and capacity enforcement.
    # Returns list of routes; each route is a list of customer ids (no depot).

    # Parse instance robustly (no imports)
    customers = {}
    depot = None
    capacity = None

    if isinstance(instance, dict):
        if 'customers' in instance and 'depot' in instance and 'vehicle_capacity' in instance:
            customers = dict(instance['customers'])
            depot = instance['depot']
            capacity = instance['vehicle_capacity']
        else:
            # heuristic fallback
            capacity = instance.get('capacity', None)
            if 'depot' in instance:
                depot = instance['depot']
            elif 0 in instance:
                depot = 0
            for k, v in instance.items():
                if isinstance(k, int) or (isinstance(k, str) and k.isdigit()):
                    idx = int(k)
                    if idx != depot:
                        customers[idx] = v
            if not capacity:
                capacity = instance.get('vehicle_capacity', capacity)
            if not depot:
                if 0 in instance:
                    depot = 0
    else:
        return []

    if depot is None or capacity is None:
        return []

    # Normalize to id -> demand
    norm = {}
    for cid, data in customers.items():
        if isinstance(data, dict) and 'demand' in data:
            norm[int(cid)] = int(data['demand'])
        elif isinstance(data, (int, float)):
            norm[int(cid)] = int(data)
        else:
            continue

    ids = sorted(norm.keys())
    if not ids:
        return []

    # Dist function: deterministic, simple based on id difference
    def dist(a, b):
        return abs(a - b)

    # Maintain set of remaining ids
    remaining = set(ids)
    routes = []

    # Start from smallest id each time to be deterministic
    while remaining:
        # pick start as smallest remaining
        start = min(remaining)
        route = [start]
        load = norm[start]
        remaining.remove(start)

        # Extend route greedily: repeatedly add a customer that fits with smallest incremental distance
