            route.append(next_cand)
            load += norm[next_cand]
            remaining.remove(next_cand)
            current = next_cand

        routes.append(route)

    # Basic repair: try to merge small routes if capacity allows (keep deterministic)
    # Attempt to merge adjacent routes if total load <= capacity and not creating depot in route
    merged = True
    while merged:
        merged = False
        i = 0
        while i < len(routes) - 1:
            a, b = routes[i], routes[i+1]
            load_a = sum(norm[c] for c in a)
            load_b = sum(norm[c] for c in b)
